using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class CreateFlappyScene {
 static Sprite square;
 static Color Hex(string s){ColorUtility.TryParseHtmlString(s,out var c);return c;}
 static GameObject Shape(string name,Vector2 pos,Vector2 size,string color,int order=0){var o=new GameObject(name);o.transform.position=pos;o.transform.localScale=size;var r=o.AddComponent<SpriteRenderer>();r.sprite=square;r.color=Hex(color);r.sortingOrder=order;return o;}
 static Text Label(Transform parent,string text,int size,Vector2 pos,Vector2 dimensions){var o=new GameObject("Text",typeof(RectTransform));o.transform.SetParent(parent,false);var r=o.GetComponent<RectTransform>();r.anchoredPosition=pos;r.sizeDelta=dimensions;var t=o.AddComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.text=text;t.fontSize=size;t.alignment=TextAnchor.MiddleCenter;t.color=Hex("#203F52");return t;}
 static Button Button(Transform p,string text,Vector2 pos){var o=new GameObject(text,typeof(RectTransform));o.transform.SetParent(p,false);var r=o.GetComponent<RectTransform>();r.anchoredPosition=pos;r.sizeDelta=new Vector2(280,60);o.AddComponent<Image>().color=Hex("#FFCF60");var b=o.AddComponent<Button>();Label(o.transform,text,24,Vector2.zero,new Vector2(280,60));return b;}
 [MenuItem("Flappy Bird/Create playable scene")]
 public static void Create(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);System.IO.Directory.CreateDirectory("Assets/Art");var tex=new Texture2D(2,2);tex.SetPixels(new[]{Color.white,Color.white,Color.white,Color.white});tex.Apply();System.IO.File.WriteAllBytes("Assets/Art/Pixel.png",tex.EncodeToPNG());AssetDatabase.ImportAsset("Assets/Art/Pixel.png");var importer=(TextureImporter)AssetImporter.GetAtPath("Assets/Art/Pixel.png");importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.spritePixelsPerUnit=2;importer.filterMode=FilterMode.Point;importer.SaveAndReimport();square=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/Pixel.png");
 var camera=new GameObject("Main Camera").AddComponent<Camera>();camera.tag="MainCamera";camera.transform.position=new Vector3(0,0,-10);camera.orthographic=true;camera.orthographicSize=5;camera.backgroundColor=Hex("#A5DDE8");camera.clearFlags=CameraClearFlags.SolidColor;
 for(int i=0;i<8;i++){Shape("Cloud",new Vector2(-10+i*3,3.1f+(i%2)*.5f),new Vector2(2,.35f),"#E9F7EF",-3);Shape("Far hills",new Vector2(-11+i*3,-3.1f),new Vector2(2.8f,2+(i%3)*.35f),"#79BBC1",-2);}
 var ground=Shape("Ground",new Vector2(0,-4.65f),new Vector2(40,1.3f),"#DCC394",2);ground.AddComponent<BoxCollider2D>();Shape("Grass",new Vector2(0,-3.98f),new Vector2(40,.18f),"#669B71",3);var ceiling=Shape("Ceiling",new Vector2(0,5.5f),new Vector2(40,1),"#A5DDE8");ceiling.AddComponent<BoxCollider2D>();
 var birdObj=Shape("Bird",Vector2.zero,new Vector2(.6f,.48f),"#FFCC55",5);birdObj.AddComponent<Rigidbody2D>();birdObj.AddComponent<BoxCollider2D>();var bird=birdObj.AddComponent<BirdController>();var eye=Shape("Eye",new Vector2(.16f,.1f),new Vector2(.09f,.09f),"#203F52",6);eye.transform.SetParent(birdObj.transform,true);var beak=Shape("Beak",new Vector2(.37f,-.03f),new Vector2(.2f,.12f),"#F08D55",6);beak.transform.SetParent(birdObj.transform,true);var wing=Shape("Wing",new Vector2(-.13f,-.08f),new Vector2(.24f,.18f),"#E8A73E",6);wing.transform.SetParent(birdObj.transform,true);
 var pair=new GameObject("PipePair");pair.AddComponent<PipeMovement>();foreach(int direction in new[]{-1,1}){var p=Shape("Pipe",new Vector2(0,direction*4.1f),new Vector2(.9f,5.4f),"#54966B",1);p.AddComponent<BoxCollider2D>();p.transform.SetParent(pair.transform,true);var rim=Shape("Pipe rim",new Vector2(0,direction*1.55f),new Vector2(1.1f,.3f),"#76B47E",2);rim.AddComponent<BoxCollider2D>();rim.transform.SetParent(pair.transform,true);}var gate=new GameObject("Score gate");gate.transform.SetParent(pair.transform);gate.transform.localPosition=new Vector3(.65f,0,0);gate.AddComponent<BoxCollider2D>().size=new Vector2(.1f,2.8f);gate.GetComponent<BoxCollider2D>().isTrigger=true;gate.AddComponent<ScoreGate>();var prefab=PrefabUtility.SaveAsPrefabAsset(pair,"Assets/Prefabs/PipePair.prefab");Object.DestroyImmediate(pair);
 var manager=new GameObject("GameManager").AddComponent<GameManager>();var score=manager.gameObject.AddComponent<ScoreManager>();var spawner=new GameObject("PipeSpawner").AddComponent<PipeSpawner>();spawner.pipePrefab=prefab;spawner.score=score;
 var canvas=new GameObject("Canvas").AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;var scaler=canvas.gameObject.AddComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1000,700);scaler.matchWidthOrHeight=.5f;canvas.gameObject.AddComponent<GraphicRaycaster>();var events=new GameObject("EventSystem");events.AddComponent<EventSystem>();events.AddComponent<StandaloneInputModule>();var ui=canvas.gameObject.AddComponent<UIManager>();ui.game=manager;ui.scoreLabel=Label(canvas.transform,"0",48,new Vector2(0,285),new Vector2(200,70));var panel=new GameObject("Menu",typeof(RectTransform));panel.transform.SetParent(canvas.transform,false);panel.GetComponent<RectTransform>().sizeDelta=new Vector2(480,540);panel.AddComponent<Image>().color=Hex("#F6F2DF");ui.panel=panel;ui.title=Label(panel.transform,"SKY HOP",46,new Vector2(0,200),new Vector2(440,70));ui.details=Label(panel.transform,"",24,new Vector2(0,50),new Vector2(440,240));ui.play=Button(panel.transform,"PLAY",new Vector2(0,-130));ui.menu=Button(panel.transform,"MAIN MENU",new Vector2(0,-210));manager.bird=bird;manager.spawner=spawner;manager.score=score;manager.ui=ui;
 PlayerSettings.companyName="Student Project";PlayerSettings.productName="Sky Hop";EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/Scenes/FlappyBird.unity");EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene("Assets/Scenes/FlappyBird.unity",true)};AssetDatabase.SaveAssets();Debug.Log("FLAPPY_SCENE_CREATED");}
}
